package pe.com.asistencia.attendance.security;
import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.jdbc.core.simple.JdbcClient; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import pe.com.asistencia.employee.repository.EmployeeRepository; import java.security.SecureRandom; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/v1/attendance-security") public class AttendanceSecurityController {
 private final JdbcClient jdbc; private final EmployeeRepository employees; private final SecureRandom random=new SecureRandom(); public AttendanceSecurityController(JdbcClient jdbc,EmployeeRepository employees){this.jdbc=jdbc;this.employees=employees;}
 @PostMapping("/devices") @ResponseStatus(HttpStatus.CREATED) public Map<String,Object> register(Authentication auth,@Valid @RequestBody DeviceRequest r){var e=employees.findByUserUsernameIgnoreCase(auth.getName()).orElseThrow(()->new ResponseStatusException(HttpStatus.FORBIDDEN,"Usuario sin empleado"));String hash=AttendanceSecurityService.hash(r.identifier());jdbc.sql("insert into registered_devices(employee_id,identifier_hash,display_name,platform,status) values(:employee,:hash,:name,:platform,'PENDING') on duplicate key update display_name=values(display_name),platform=values(platform)").param("employee",e.getId()).param("hash",hash).param("name",r.displayName()).param("platform",r.platform()).update();return Map.of("status","PENDING");}
 @GetMapping("/devices") @PreAuthorize("hasRole('ADMIN')") public List<Map<String,Object>> devices(){return jdbc.sql("select d.id,e.employee_code,d.display_name,d.platform,d.status,d.created_at,d.last_used_at,d.revoked_at,d.revocation_reason from registered_devices d join employees e on e.id=d.employee_id order by d.created_at desc").query().listOfRows();}
 @PatchMapping("/devices/{id}") @PreAuthorize("hasRole('ADMIN')") public void reviewDevice(Authentication auth,@PathVariable Long id,@Valid @RequestBody DeviceReview r){Long user=userId(auth);Long employee=jdbc.sql("select employee_id from registered_devices where id=:id").param("id",id).query(Long.class).optional().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Dispositivo no encontrado"));if(r.approved())jdbc.sql("update registered_devices set status='REVOKED',revoked_by=:user,revoked_at=current_timestamp,revocation_reason='REPLACED_BY_NEW_DEVICE' where employee_id=:employee and id<>:id and status='APPROVED'").param("user",user).param("employee",employee).param("id",id).update();jdbc.sql("update registered_devices set status=:status,approved_by=:user,approved_at=current_timestamp,revoked_by=null,revoked_at=null,revocation_reason=null where id=:id").param("status",r.approved()?"APPROVED":"REJECTED").param("user",user).param("id",id).update();}
 @PatchMapping("/devices/{id}/revoke") @PreAuthorize("hasRole('ADMIN')") public void revokeDevice(Authentication auth,@PathVariable Long id,@Valid @RequestBody DeviceRevoke r){int count=jdbc.sql("update registered_devices set status='REVOKED',revoked_by=:user,revoked_at=current_timestamp,revocation_reason=:reason where id=:id").param("user",userId(auth)).param("reason",r.reason()).param("id",id).update();if(count==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Dispositivo no encontrado");}
 @PostMapping("/qr") @PreAuthorize("hasRole('ADMIN')") public QrResponse createQr(Authentication auth,@Valid @RequestBody QrRequest r){byte[] bytes=new byte[24];random.nextBytes(bytes);String code=Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);Instant now=Instant.now(),expires=now.plusSeconds(r.validSeconds());Long user=jdbc.sql("select id from users where lower(username)=lower(:username)").param("username",auth.getName()).query(Long.class).single();jdbc.sql("update dynamic_qr_challenges set active=false where site_id=:site and active=true").param("site",r.siteId()).update();jdbc.sql("insert into dynamic_qr_challenges(site_id,code_hash,valid_from,expires_at,created_by) values(:site,:hash,:from,:to,:user)").param("site",r.siteId()).param("hash",AttendanceSecurityService.hash(code)).param("from",now).param("to",expires).param("user",user).update();return new QrResponse(code,expires);}
 @GetMapping("/attempts") @PreAuthorize("hasRole('ADMIN')") public List<Map<String,Object>> attempts(@RequestParam(defaultValue="100") int limit){return jdbc.sql("select * from punch_attempts order by occurred_at desc limit :limit").param("limit",Math.min(limit,500)).query().listOfRows();}
 private Long userId(Authentication auth){return jdbc.sql("select id from users where lower(username)=lower(:username)").param("username",auth.getName()).query(Long.class).single();}
 public record DeviceRequest(@NotBlank @Size(max=300) String identifier,@NotBlank @Size(max=120) String displayName,@NotBlank @Size(max=40) String platform){} public record DeviceReview(boolean approved){} public record DeviceRevoke(@NotBlank @Size(max=255) String reason){} public record QrRequest(@NotNull Long siteId,@Min(30) @Max(3600) int validSeconds){} public record QrResponse(String code,Instant expiresAt){}
}
